// next.config.ts
import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  cacheComponents: true, // Unlocks "use cache" + PPR
};

export default nextConfig;

// app/dashboard/page.tsx
// No special exports. No config. Just vibes.

export default async function DashboardPage() {
  // This runs on EVERY request — fresh data, every time
  const res = await fetch("https://api.example.com/user-stats");
  const stats = await res.json();

  return (
    <main>
      <h1>Dashboard</h1>
      <p>Active users: {stats.activeUsers}</p>
      <p>Revenue today: ${stats.revenue}</p>
    </main>
  );
}

// Next.js 16: params are async now
export default async function ProductPage({
  params,
  searchParams,
}: {
  params: Promise<{ slug: string }>;
  searchParams: Promise<{ sort?: string }>;
}) {
  const { slug } = await params;       // Must await!
  const { sort } = await searchParams;  // Must await!

  const product = await getProduct(slug);
  return <ProductView product={product} sort={sort} />;
}

