// components/layout/header.tsx
"use client";

import { useState, useEffect } from "react";
import { usePathname } from "next/navigation";

export function Header({ hasSession, darkMode }: HeaderProps) {
  const [isHydrated, setIsHydrated] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const pathname = usePathname();

  // Hydration guard: avoid SSR/client mismatch
  useEffect(() => {
    setIsHydrated(true);
  }, []);

  // Use server-provided value until hydrated, then switch to live data
  const isSignedIn = isHydrated ? !!session : (hasSession ?? false);

  // Close mobile menu on resize (desktop breakpoint)
  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth >= 1024) setIsMobileMenuOpen(false);
    };
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  return (
    <header className="header-scroll fixed top-0 z-50 bg-background/80 backdrop-blur-xl">
      {/* Navigation, mobile menu, auth buttons... */}
    </header>
  );
}

// BAD: "use client" at the layout level. Everything is client-rendered.
// Your server components weep silently.

// GOOD: Server layout wrapping client islands
// app/layout.tsx (Server Component — no "use client")
import { Header } from "@/components/layout/header";
import { Footer } from "@/components/layout/footer";

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html>
      <body>
        <Header hasSession={!!session} />  {/* Client island */}
        {children}                          {/* Server-rendered content */}
        <Footer />                          {/* Static, server-rendered */}
      </body>
    </html>
  );
}

// app/product/[id]/page.tsx
import { Suspense } from "react";
import { cacheLife, cacheTag } from "next/cache";

export default function ProductPage() {
  return (
    <main>
      {/* STATIC: Instant. Prerendered. Zero latency. */}
      <nav>
        <a href="/">Home</a> / <a href="/products">Products</a>
      </nav>

      {/* CACHED: Fetches data but included in static shell */}
      <ProductDetails />

      {/* DYNAMIC: Streams in per-request. User-specific. */}
      <Suspense fallback={<CartSkeleton />}>
        <UserCart />
      </Suspense>
    </main>
  );
}

// This component is cached (ISR-style) — same for everyone
async function ProductDetails() {
  "use cache";
  cacheLife("hours");
  cacheTag("products");

  const product = await getProduct();
  return (
    <section>
      <h1>{product.name}</h1>
      <p>{product.description}</p>
      <p className="text-2xl font-bold">${product.price}</p>
    </section>
  );
}

// This component is dynamic — runs on every request
async function UserCart() {
  const cart = await getUserCart(); // reads cookies internally
  return (
    <aside>
      <p>Your cart: {cart.itemCount} items</p>
    </aside>
  );
}

// app/dashboard/page.tsx
import { Suspense } from "react";
import { cacheLife, cacheTag } from "next/cache";
import { DashboardCharts } from "@/components/dashboard-charts";

export default function DashboardPage() {
  return (
    <main>
      {/* SSG: Static marketing banner — same for everyone */}
      <section className="bg-primary text-primary-foreground p-4 rounded-lg">
        <p>New feature: AI-powered analytics is here!</p>
      </section>

      {/* ISR: Cached global metrics — updates hourly */}
      <Suspense fallback={<MetricsSkeleton />}>
        <GlobalMetrics />
      </Suspense>

      {/* SSR: User-specific data — fresh on every request */}
      <Suspense fallback={<ChartsSkeleton />}>
        <UserAnalytics />
      </Suspense>

      {/* CSR: Interactive chart controls — client-side only */}
      <DashboardCharts />
    </main>
  );
}

async function GlobalMetrics() {
  "use cache";
  cacheLife("hours");
  cacheTag("global-metrics");

  const metrics = await fetch("https://api.example.com/metrics")
    .then((r) => r.json());

  return (
    <div className="grid grid-cols-3 gap-4">
      <Stat label="Total Users" value={metrics.users} />
      <Stat label="Revenue" value={metrics.revenue} />
      <Stat label="Uptime" value={metrics.uptime} />
    </div>
  );
}

async function UserAnalytics() {
  // No "use cache" — dynamic by default, runs per-request
  const session = await getSession();
  const analytics = await getUserAnalytics(session.userId);

  return (
    <section>
      <h2>Your Analytics</h2>
      <p>Page views this week: {analytics.pageViews}</p>
      <p>Conversion rate: {analytics.conversionRate}%</p>
    </section>
  );
}
